4	import { useIntl } from "react-intl";
5	
6	import { messages } from "./messages";
7	import { type OrderDiscountCommonInput } from "./types";
8	
9	const numbersRegex = /^[0-9]*\.?[0-9]+$/;
10	
11	export interface DiscountFormData {
12	  value: string;
13	  reason: string;
14	  calculationMode: DiscountValueTypeEnum;
15	}
16	
17	interface UseDiscountFormProps {
18	  maxPrice: MoneyFragment;
19	  existingDiscount?: OrderDiscountCommonInput;
20	  isOpen?: boolean;
21	}
22	
23	const parseNumericValue = (value: string): number => parseFloat(value) || 0;
24	
25	function convertValue(
26	  value: number,
27	  maxAmount: number,
28	  from: DiscountValueTypeEnum,
29	  to: DiscountValueTypeEnum,
30	): string {
31	  if (value === 0 || maxAmount === 0 || from === to) {
32	    return value.toString();
33	  }
34	
35	  const toFixed = from === DiscountValueTypeEnum.PERCENTAGE && to === DiscountValueTypeEnum.FIXED;
36	  const raw = toFixed ? (value * maxAmount) / 100 : (value / maxAmount) * 100;
37	
38	  return (Math.round(raw * 100) / 100).toString();
39	}
40	
41	export const useDiscountForm = ({ maxPrice, existingDiscount, isOpen }: UseDiscountFormProps) => {
42	  const intl = useIntl();
43	  const { currency, amount: maxAmount } = maxPrice;
44	  const previousCalculationMode = useRef<DiscountValueTypeEnum>(
45	    existingDiscount?.calculationMode || DiscountValueTypeEnum.PERCENTAGE,
46	  );
47	
48	  const getDefaultValues = useCallback((): DiscountFormData => {
49	    const calculationMode = existingDiscount?.calculationMode || DiscountValueTypeEnum.PERCENTAGE;
50	    let value = "";
51	
52	    if (existingDiscount?.value) {
53	      const stringifiedValue = existingDiscount.value.toString();
54	
55	      value =
56	        calculationMode === DiscountValueTypeEnum.FIXED
57	          ? parseFloat(stringifiedValue).toString()
58	          : stringifiedValue;
59	    }
60	
61	    return {
62	      calculationMode,
63	      reason: existingDiscount?.reason || "",
64	      value,
65	    };
66	  }, [existingDiscount?.calculationMode, existingDiscount?.reason, existingDiscount?.value]);
67	
68	  const { control, watch, setValue, reset, getValues } = useForm<DiscountFormData>({
69	    defaultValues: getDefaultValues(),
70	  });
71	
72	  const calculationMode = watch("calculationMode");
73	  const value = watch("value");
74	  const reason = watch("reason");
75	
76	  const [prevIsOpen, setPrevIsOpen] = useState(isOpen);
77	
78	  if (isOpen !== prevIsOpen) {
79	    setPrevIsOpen(isOpen);
80	
81	    const data = getDefaultValues();
82	
83	    reset(data);
84	    previousCalculationMode.current = data.calculationMode;
85	  }
86	
87	  const handleCalculationModeChange = useCallback(
88	    (newMode: DiscountValueTypeEnum) => {
89	      const rawValue = getValues("value");
90	
91	      if (rawValue === "") {
92	        setValue("calculationMode", newMode);
93	        previousCalculationMode.current = newMode;
94	
95	        return;
96	      }
97	
98	      const currentValue = parseNumericValue(rawValue);
99	      const converted = convertValue(
100	        currentValue,
101	        maxAmount,
102	        previousCalculationMode.current,
103	        newMode,
104	      );
105	
106	      setValue("value", converted);
107	      setValue("calculationMode", newMode);
108	      previousCalculationMode.current = newMode;
109	    },
110	    [getValues, maxAmount, setValue],
111	  );
112	
113	  // Validation is derived rather than stored in formState.errors because
114	  // the error depends on both `value` and `calculationMode` (cross-field),
115	  // and using setError/clearErrors in an effect causes infinite re-renders
116	  // with react-hook-form's proxy-based formState subscriptions.
117	  const valueErrorMsg = useMemo(() => {
118	    if (value === "") {
119	      return null;
120	    }
121	
122	    const isPercentage = calculationMode === DiscountValueTypeEnum.PERCENTAGE;
123	    const topAmount = isPercentage ? 100 : maxAmount;
124	    const parsedValue = parseNumericValue(value);
125	
126	    if (!numbersRegex.test(value)) {
127	      return intl.formatMessage(messages.invalidValue);
128	    }
129	
130	    if (parsedValue > topAmount) {
131	      return isPercentage
132	        ? intl.formatMessage(messages.valueBiggerThan100)
133	        : intl.formatMessage(messages.valueBiggerThanPrice);
134	    }
135	
136	    return null;
137	  }, [value, calculationMode, maxAmount, intl]);
138	
139	  const parsedValue = parseNumericValue(value);
140	  const valueFieldSymbol = calculationMode === DiscountValueTypeEnum.FIXED ? currency : "%";
141	
142	  const hasChanges = useMemo(() => {
143	    const initialValues = getDefaultValues();
144	
145	    return (
146	      calculationMode !== initialValues.calculationMode ||
147	      reason !== initialValues.reason ||
148	      parsedValue !== parseNumericValue(initialValues.value)
149	    );
150	  }, [calculationMode, reason, parsedValue, getDefaultValues]);
151	
152	  const isSubmitDisabled = !parsedValue || !!valueErrorMsg || !hasChanges;
153	
154	  const getDiscountData = useCallback(
155	    (): OrderDiscountCommonInput => ({
156	      calculationMode: getValues("calculationMode"),
157	      reason: getValues("reason"),
158	      value: parseNumericValue(getValues("value")),
159	    }),
160	    [getValues],
161	  );
162	
163	  return {
164	    control,
165	    setValue,
166	    getValues,
167	    valueFieldSymbol,
168	    isSubmitDisabled,
169	    getDiscountData,
170	    valueErrorMsg,
171	    onCalculationModeChange: handleCalculationModeChange,
172	  };
173	};
